#include <iostream>

// Prototype specifying default arguments for all three dimensions
int boxVolume(int length = 1, int width = 1, int height = 1);

int main() {
    // 0 arguments: uses 1, 1, 1
    std::cout << "Default: " << boxVolume() << "\n";
    // 1 argument: length = 10, uses default width=1, height=1
    std::cout << "Length 10: " << boxVolume(10) << "\n";
    // 2 arguments: length = 10, width = 5, uses default height=1
    std::cout << "Length 10, Width 5: " << boxVolume(10, 5) << "\n";
    // 3 arguments: length = 10, width = 5, height = 2
    std::cout << "Length 10, Width 5, Height 2: " << boxVolume(10, 5, 2) << "\n";
    return 0;
}

int boxVolume(int length, int width, int height) {
    return length * width * height;
}

#include <iostream>

int number = 7; // global variable

int main() {
    double number = 10.5; // local variable hiding the global int

    std::cout << "Local double value of number = " << number << "\n";
    std::cout << "Global int value of number = " << ::number << "\n";
    return 0;
}

#include <iostream>

// Overloaded function for int
int square(int x) {
    std::cout << "square of integer " << x << " is ";
    return x * x;
}

// Overloaded function for double
double square(double y) {
    std::cout << "square of double " << y << " is ";
    return y * y;
}

int main() {
    std::cout << square(7) << "\n";   // resolves to int version
    std::cout << square(7.5) << "\n"; // resolves to double version
    return 0;
}
